38	const PROCESSING_FEE = 5;
39	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
40	
41	const percentOf = (amount: number, percent: number): number =>
42	  (amount * percent) / 100;
43	
44	// The MHPCO always rounds in its own favour: premiums (which the customer
45	// pays) go up. Payouts round down, but no test demands that yet.
46	const roundedUpInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
47	
48	const itemBasePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
49	
50	// Three components of the same type form a "building block" priced as a unit
51	// rather than per item.
52	const BLOCK_SIZE = 3;
53	const BLOCK_BASE_PREMIUM = 60;
54	
55	const groupedByType = (items: Item[]): Item[][] => {
56	  const groups = new Map<InsurableItemType, Item[]>();
57	
58	  for (const item of items) {
59	    const group = groups.get(item.type) ?? [];
60	    group.push(item);
61	    groups.set(item.type, group);
62	  }
63	
64	  return [...groups.values()];
65	};
66	
67	// A group of exactly BLOCK_SIZE alike items is priced as a block; any other
68	// group is priced per item.
69	const groupBasePremiumOf = (group: Item[]): number =>
70	  group.length === BLOCK_SIZE
71	    ? BLOCK_BASE_PREMIUM
72	    : group.reduce((sum, item) => sum + itemBasePremiumOf(item), 0);
73	
74	const policyBasePremiumOf = (items: Item[]): number =>
75	  groupedByType(items).reduce(
76	    (sum, group) => sum + groupBasePremiumOf(group),
77	    0,
78	  );
79	
80	const quote = (step: QuoteStep): QuoteResult => {
81	  const basePremium = policyBasePremiumOf(step.items);
82	  const initialAssessmentSurcharge = percentOf(
83	    basePremium,
84	    INITIAL_ASSESSMENT_SURCHARGE_PERCENT,
85	  );
86	
87	  return {
88	    premium: roundedUpInMHPCOsFavour(
89	      basePremium + initialAssessmentSurcharge + PROCESSING_FEE,
90	    ),
91	  };
92	};
93	
94	export const runScenario = (scenario: Scenario): ScenarioResult => {
95	  return { results: scenario.steps.map(quote) };
96	};
