cat > /tmp/equiv.mjs <<'EOF'
const BASE={sword:100,amulet:60,staff:80,potion:40,rune:25,moonstone:25};
const TYPES=Object.keys(BASE);
const itemBase=i=>BASE[i.type];

// ORIGINAL (pre-refactor)
const oldGrouped=items=>{const g=new Map();for(const it of items){const grp=g.get(it.type)??[];grp.push(it);g.set(it.type,grp);}return [...g.values()];};
const oldGroupBase=grp=>grp.length===3?60:grp.reduce((s,i)=>s+itemBase(i),0);
const oldPolicy=items=>oldGrouped(items).reduce((s,g)=>s+oldGroupBase(g),0);

// REFACTORED
const sumOf=a=>a.reduce((t,x)=>t+x,0);
const newGroups=items=>{const g=new Map();for(const it of items){g.set(it.type,[...(g.get(it.type)??[]),it]);}return [...g.values()];};
const formsBlock=a=>a.length===3;
const newGroupBase=a=>formsBlock(a)?60:sumOf(a.map(itemBase));
const newPolicy=items=>sumOf(newGroups(items).map(newGroupBase));

let checked=0,bad=0;
for(let trial=0;trial<200000;trial++){
  const n=Math.floor(Math.random()*9);
  const items=Array.from({length:n},()=>({type:TYPES[Math.floor(Math.random()*TYPES.length)]}));
  const a=oldPolicy(items),b=newPolicy(items);
  checked++;
  if(a!==b){bad++;if(bad<4)console.log("MISMATCH",JSON.stringify(items.map(i=>i.type)),a,b);}
  // also assert grouping shape (multiset of group sizes+types) is identical
  const sig=gs=>JSON.stringify(gs.map(g=>[g[0].type,g.length]).sort());
  if(n&&sig(oldGrouped(items))!==sig(newGroups(items))){bad++;if(bad<6)console.log("GROUPDIFF",JSON.stringify(items.map(i=>i.type)));}
}
console.log(`checked=${checked} mismatches=${bad}`);
EOF
